'use strict';
// Preserve native form values and existing change handlers while styling the popup.
document.querySelectorAll('select').forEach((select,index)=>{
 const wrap=document.createElement('div');wrap.className='gold-select';select.before(wrap);wrap.append(select);select.classList.add('control-native');select.tabIndex=-1;select.setAttribute('aria-hidden','true');
 const button=document.createElement('button');button.type='button';button.className='gold-select-trigger';button.setAttribute('role','combobox');button.setAttribute('aria-haspopup','listbox');button.setAttribute('aria-expanded','false');
 button.setAttribute('aria-label',select.getAttribute('aria-label')||select.closest('label')?.firstChild.textContent.trim()||'Chọn giá trị');
 const list=document.createElement('div');list.className='gold-select-options';list.id='gold-options-'+index;list.setAttribute('role','listbox');list.hidden=true;button.setAttribute('aria-controls',list.id);wrap.append(button,list);
 let active=0;
 function sync(){button.textContent=select.selectedOptions[0]?.textContent||'Chọn giá trị';button.disabled=select.disabled;wrap.hidden=select.hidden;active=select.selectedIndex;list.replaceChildren();Array.from(select.options).forEach((option,i)=>{const item=document.createElement('div');item.id=list.id+'-'+i;item.className='gold-select-option';item.setAttribute('role','option');item.setAttribute('aria-selected',String(option.selected));item.textContent=option.textContent;item.addEventListener('click',()=>choose(i));list.append(item);});}
 function close(){list.hidden=true;button.setAttribute('aria-expanded','false');button.removeAttribute('aria-activedescendant');}
 function highlight(){Array.from(list.children).forEach((item,i)=>item.classList.toggle('highlighted',i===active));button.setAttribute('aria-activedescendant',list.id+'-'+active);const item=list.children[active];if(item){if(item.offsetTop<list.scrollTop)list.scrollTop=item.offsetTop;else if(item.offsetTop+item.offsetHeight>list.scrollTop+list.clientHeight)list.scrollTop=item.offsetTop+item.offsetHeight-list.clientHeight;}}
 function open(){document.dispatchEvent(new Event('gold-select-close'));sync();list.hidden=false;button.setAttribute('aria-expanded','true');highlight();}
 function choose(i){if(select.options[i].disabled)return;select.selectedIndex=i;select.dispatchEvent(new Event('change',{bubbles:true}));sync();close();button.focus({preventScroll:true});}
 button.onclick=e=>{e.preventDefault();list.hidden?open():close();};list.addEventListener('click',e=>e.preventDefault());
 button.onkeydown=e=>{if(['ArrowDown','ArrowUp','Home','End','Enter',' ','Escape','Tab'].includes(e.key)){if(e.key==='Tab'){close();return;}e.preventDefault();if(e.key==='Escape'){close();return;}if(e.key==='Enter'||e.key===' '){list.hidden?open():choose(active);return;}if(list.hidden)open();else active=e.key==='Home'?0:e.key==='End'?select.options.length-1:Math.max(0,Math.min(select.options.length-1,active+(e.key==='ArrowDown'?1:-1)));highlight();}else if(e.key.length===1){const options=Array.from(select.options);const found=options.findIndex((o,i)=>i>active&&o.text.toLocaleLowerCase().startsWith(e.key.toLocaleLowerCase()));if(found>=0){if(list.hidden)open();active=found;highlight();}}};
 document.addEventListener('gold-select-close',close);document.addEventListener('click',e=>{if(!wrap.contains(e.target))close();});select.addEventListener('change',sync);
 new MutationObserver(sync).observe(select,{attributes:true,attributeFilter:['hidden','disabled'],childList:true,subtree:true});select.form?.addEventListener('reset',()=>queueMicrotask(sync));const dialog=select.closest('dialog');if(dialog)new MutationObserver(()=>{sync();close();}).observe(dialog,{attributes:true,attributeFilter:['open']});sync();
});
document.querySelectorAll('input[type=file]').forEach((input,index)=>{
 const wrap=document.createElement('div');wrap.className='gold-upload';input.before(wrap);wrap.append(input);input.classList.add('control-native');if(!input.id)input.id='gold-upload-'+index;
 const label=document.createElement('label');label.className='gold-upload-button';label.htmlFor=input.id;label.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M12 16V4m-4 4 4-4 4 4M4 15v5h16v-5"/></svg> Chọn ảnh';
 const name=document.createElement('span');name.className='gold-upload-name';const clear=document.createElement('button');clear.type='button';clear.className='gold-upload-clear';clear.textContent='Bỏ chọn';clear.onclick=()=>{input.value='';sync();};wrap.append(label,name,clear);
 function sync(){name.textContent=input.files[0]?.name||'Chưa chọn ảnh · PNG / JPG';name.title=name.textContent;clear.hidden=!input.files.length;}
 input.addEventListener('change',sync);input.form?.addEventListener('reset',()=>queueMicrotask(sync));sync();
});
for(const [field,onText,offText,labelText] of [['isVisible','Đang hiển thị ứng dụng','Đang ẩn ứng dụng','Hiển thị ứng dụng'],['isPublished','Xuất bản bài viết','Lưu bản nháp','Xuất bản bài viết']]){
 const visibility=document.querySelector('input[name='+field+']');if(!visibility)continue;
 const label=visibility.closest('label');label.classList.add('visibility-control');visibility.classList.add('control-native');visibility.tabIndex=-1;visibility.setAttribute('aria-hidden','true');const button=document.createElement('button');button.type='button';button.className='visibility-button';button.setAttribute('role','switch');button.setAttribute('aria-label',labelText);label.append(button);for(const node of Array.from(label.childNodes))if(node.nodeType===Node.TEXT_NODE)node.textContent='';
 const sync=()=>{button.setAttribute('aria-checked',String(visibility.checked));button.innerHTML='<span class="visibility-track"><span></span></span><span>'+ (visibility.checked?onText:offText)+'</span>';};button.onclick=e=>{e.preventDefault();visibility.checked=!visibility.checked;visibility.dispatchEvent(new Event('change',{bubbles:true}));};visibility.addEventListener('change',sync);visibility.form?.addEventListener('reset',()=>queueMicrotask(sync));new MutationObserver(sync).observe(visibility.closest('dialog'),{attributes:true,attributeFilter:['open']});sync();
}